	CValve* subtitle = CValve::Create("SUBTITLE_CONTROLLER", VALVE_TYPE::VTYPE_TEMP);
	CValve* dialog = CValve::Create("DIALOG_CONTROLLER", VALVE_TYPE::VTYPE_TEMP);
