_zanim_cmd_hdr * zAnimLoadUIAppMenu(_zrdr *reader)
{
	/* 0x1d0330 (text path): UI_APP_COMMAND - an 8-byte timeless record: +0x4 the TYPE's
	 * UICommandTable id, +0x5 the ARGUMENT's name index (no node). Its tick does nothing
	 * (0x1d0130). Written, untested (no retail data takes the text path). */
	_zanim_cmd_hdr* cmd = static_cast<_zanim_cmd_hdr*>(_calloc(1, 8, "zanim_menu.cpp", 4317));
	u8* bytes = reinterpret_cast<u8*>(cmd);
	cmd->timeless = true;
	cmd->data_size = 8;
	bytes[4] = GetUICommandType(zrdr_findstring(reader, "TYPE"));
	char* argument = zrdr_findstring(reader, "ARGUMENT");

	if (argument != NULL && *argument != '\0')
	{
		char name[128];
		strcpy(name, argument);
		bytes[5] = ZAnim.m_CurAnim->AddName(name);
	}

	return cmd;
}

/* @socom-skeleton stub zAnimUIMenuTick__FP14_zanim_cmd_hdrPf */
bool zAnimUIMenuTick(_zanim_cmd_hdr *header, float *dT)
{
	/* 0x1d0140: a command for a node's 2D object goes to its TickZAnimCmd; else the UI
	 * function of that id (looked up directly, then by search) runs. */
	C2DAnimCmdHdr* cmd = reinterpret_cast<C2DAnimCmdHdr*>(header);
	CZAnim* anim = ZAnim.m_CurAnim;
	bool handled = false;
	bool result = true;

	if (cmd->node_ref_index != 0)
	{
		C2D* object = NULL;
		anim->Refresh(false);
		zdb::CNode* node = anim->GetNode(cmd->node_ref_index, false);

		if (node != NULL)
		{
			zdb::CVisual* visual = node->GetFirstVisual();
			C2DVisual* visual2d = visual ? visual->Get2DVisual() : NULL;

			if (visual2d != NULL)
				object = visual2d->m_2d;
		}

		if (object != NULL)
			handled = object->TickZAnimCmd(header, dT, &result);
	}

	if (handled)
		return result;

	anim->GetName(cmd->m_argument_index);
	u32 id = cmd->m_command_type;
#ifdef SOCOM_PORT
	{
		static u32 portCalls = 0;

		if (portCalls++ < 40)
		{
			const char* portName = "?";

			for (u32 i = 0; UICommandTable[i].id != 0; i++)
			{
				if (UICommandTable[i].id == id)
					portName = UICommandTable[i].name;
			}

			SOCOM_PORT_TRACE("UI: UI_COMMAND 0x%x (%s) arg '%s'", id, portName,
				anim->GetName(cmd->m_argument_index) ? anim->GetName(cmd->m_argument_index) : "");
		}
	}
#endif

	/* port: the ELF reads UICommandTable[id] past the table's end for the objects' own command
	 * types (0x95 on, a command whose node has no 2D object); the port tests the index first */
	if (id < sizeof(UICommandTable) / sizeof(UICommandTable[0]) && UICommandTable[id].id == id)
	{
		if (UICommandTable[id].func != NULL)
			return UICommandTable[id].func(cmd, dT);
	}
	else
	{
		for (u32 i = 0; UICommandTable[i].id != 0; i++)
		{
			if (UICommandTable[i].id == id && UICommandTable[i].func != NULL)
				return UICommandTable[i].func(cmd, dT);
		}
	}

	return true;
}

